mapper.sql:
WITH d AS (
    SELECT districtid, shape
    FROM ${t.district}
    WHERE municipalityname = #{muni}

      AND districtid IN #{id}

)

mapper.select:
SELECT districtid AS makani_id, nameenglish AS makani_name, namearabic AS name_ar, round((ST_Area(ST_Transform(shape, 32640)) / 1e6)::numeric, 3) AS area_km2, ST_X(ST_PointOnSurface(shape)) AS centroid_lon, ST_Y(ST_PointOnSurface(shape)) AS centroid_lat, ST_XMin(shape) AS min_lon, ST_YMin(shape) AS min_lat, ST_XMax(shape) AS max_lon, ST_YMax(shape) AS max_lat, encode(ST_AsEWKB(ST_Multi(ST_SimplifyPreserveTopology(ST_Force2D(shape), #{tol}))), 'hex') AS boundary_hex, encode(ST_AsEWKB(ST_Multi(ST_Force2D(shape))), 'hex') AS scope_hex FROM ${t.district} WHERE municipalityname = #{muni}
AND districtid IN #{id}
ORDER BY nameenglish
